const { projectKey, issueTypeId, summary, description, priority, labels, assigneeAccountId, parentKey } = $.input;

if (!projectKey || !issueTypeId || !summary) throw new Error('projectKey, issueTypeId, and summary are required');

// Convert plain text to Atlassian Document Format (ADF)
function textToAdf(text) {
  if (!text) return undefined;
  const paragraphs = text.split('\n').filter(line => line.trim() !== '');
  return {
    type: 'doc',
    version: 1,
    content: paragraphs.map(p => ({
      type: 'paragraph',
      content: [{ type: 'text', text: p }]
    }))
  };
}

const fields = {
  project: { key: projectKey },
  issuetype: { id: issueTypeId },
  summary: summary
};

if (description) fields.description = textToAdf(description);
if (priority) fields.priority = { name: priority };
if (labels && labels.length > 0) fields.labels = labels;
if (assigneeAccountId) fields.assignee = { accountId: assigneeAccountId };
if (parentKey) fields.parent = { key: parentKey };

return { fields };

const resp = $.steps.createIssue.response || {};
const projectKey = $.input.projectKey;

return {
  id: resp.id || '',
  key: resp.key || '',
  self: resp.self || '',
  projectKey: projectKey,
  summary: $.input.summary,
  created: !!resp.id,
  summary_text: resp.id
    ? `Created ${resp.key}: "${$.input.summary}" in project ${projectKey}`
    : 'Failed to create issue'
};
